18	package org.apache.solr.servlet;
19	
20	import static org.apache.solr.core.RateLimiterConfig.RL_CONFIG_KEY;
21	
22	import com.fasterxml.jackson.databind.ObjectMapper;
23	import java.io.IOException;
24	import java.util.Map;
25	import org.apache.solr.client.solrj.SolrRequest;
26	import org.apache.solr.client.solrj.request.beans.RateLimiterPayload;
27	import org.apache.solr.common.cloud.SolrZkClient;
28	import org.apache.solr.common.cloud.ZkStateReader;
29	import org.apache.solr.common.util.Utils;
30	import org.apache.solr.core.RateLimiterConfig;
31	import org.apache.solr.util.SolrJacksonAnnotationInspector;
32	import org.apache.zookeeper.KeeperException;
33	import org.apache.zookeeper.data.Stat;
34	
35	/**
36	 * Implementation of RequestRateLimiter specific to query request types. Most of the actual work is
37	 * delegated to the parent class but specific configurations and parsing are handled by this class.
38	 */
39	public class QueryRateLimiter extends RequestRateLimiter {
40	  private static final ObjectMapper mapper = SolrJacksonAnnotationInspector.createObjectMapper();
41	
42	  public QueryRateLimiter(SolrZkClient solrZkClient) {
43	    super(constructQueryRateLimiterConfig(solrZkClient));
44	  }
45	
46	  public void processConfigChange(Map<String, Object> properties) throws IOException {
47	    RateLimiterConfig rateLimiterConfig = getRateLimiterConfig();
48	    byte[] configInput = Utils.toJSON(properties.get(RL_CONFIG_KEY));
49	
50	    if (configInput == null || configInput.length == 0) {
51	      return;
52	    }
53	
54	    RateLimiterPayload rateLimiterMeta = mapper.readValue(configInput, RateLimiterPayload.class);
55	
56	    constructQueryRateLimiterConfigInternal(rateLimiterMeta, rateLimiterConfig);
57	  }
58	
59	  // To be used in initialization
60	  @SuppressWarnings({"unchecked"})
61	  private static RateLimiterConfig constructQueryRateLimiterConfig(SolrZkClient zkClient) {
62	    try {
63	
64	      if (zkClient == null) {
65	        return new RateLimiterConfig(SolrRequest.SolrRequestType.QUERY);
66	      }
67	
68	      RateLimiterConfig rateLimiterConfig =
69	          new RateLimiterConfig(SolrRequest.SolrRequestType.QUERY);
70	      Map<String, Object> clusterPropsJson =
71	          (Map<String, Object>)
72	              Utils.fromJSON(zkClient.getData(ZkStateReader.CLUSTER_PROPS, null, new Stat(), true));
73	      byte[] configInput = Utils.toJSON(clusterPropsJson.get(RL_CONFIG_KEY));
74	
75	      if (configInput.length == 0) {
76	        // No Rate Limiter configuration defined in clusterprops.json. Return default configuration
77	        // values
78	        return rateLimiterConfig;
79	      }
80	
81	      RateLimiterPayload rateLimiterMeta = mapper.readValue(configInput, RateLimiterPayload.class);
82	
83	      constructQueryRateLimiterConfigInternal(rateLimiterMeta, rateLimiterConfig);
84	
85	      return rateLimiterConfig;
86	    } catch (KeeperException.NoNodeException e) {
87	      return new RateLimiterConfig(SolrRequest.SolrRequestType.QUERY);
88	    } catch (KeeperException | InterruptedException e) {
89	      throw new RuntimeException(
90	          "Error reading cluster property", SolrZkClient.checkInterrupted(e));
91	    } catch (IOException e) {
92	      throw new RuntimeException("Encountered an IOException " + e.getMessage());
93	    }
94	  }
95	
96	  private static void constructQueryRateLimiterConfigInternal(
97	      RateLimiterPayload rateLimiterMeta, RateLimiterConfig rateLimiterConfig) {
98	
99	    if (rateLimiterMeta == null) {
100	      // No Rate limiter configuration defined in clusterprops.json
101	      return;
102	    }
103	
104	    if (rateLimiterMeta.allowedRequests != null) {
105	      rateLimiterConfig.allowedRequests = rateLimiterMeta.allowedRequests.intValue();
106	    }
107	
108	    if (rateLimiterMeta.enabled != null) {
109	      rateLimiterConfig.isEnabled = rateLimiterMeta.enabled;
110	    }
111	
112	    if (rateLimiterMeta.guaranteedSlots != null) {
113	      rateLimiterConfig.guaranteedSlotsThreshold = rateLimiterMeta.guaranteedSlots;
114	    }
115	
116	    if (rateLimiterMeta.slotBorrowingEnabled != null) {
117	      rateLimiterConfig.isSlotBorrowingEnabled = rateLimiterMeta.slotBorrowingEnabled;
118	    }
119	
120	    if (rateLimiterMeta.slotAcquisitionTimeoutInMS != null) {
121	      rateLimiterConfig.waitForSlotAcquisition =
122	          rateLimiterMeta.slotAcquisitionTimeoutInMS.longValue();
123	    }
124	  }
125	}
